def iso_duration_seconds(s):
    if not s or s[0] != 'P':
        raise ValueError
    i = 1
    # week only pattern: digits then 'W' and end
    j = i
    while j < len(s) and s[j].isdigit():
        j += 1
    if j < len(s) and s[j] == 'W' and j+1 == len(s):
        weeks = float(s[i:j])
        return weeks * 7 * 86400
    # optional day count
    day_seconds = 0.0
    if i < len(s) and s[i].isdigit():
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        if i < len(s) and s[i] == 'D':
            day_seconds = float(s[start:i]) * 86400
            i += 1
        else:
            raise ValueError
    # optional 'T'
    if i < len(s) and s[i] == 'T':
        i += 1
    # parse hour, minute, second counts in order H, M, S, at least one present
    total = day_seconds
    last_unit_idx = -1
    any_unit = False
    units = {'H':0, 'M':1, 'S':2}
    while i < len(s):
        # parse number (digits optionally with a single '.')
        if not (s[i].isdigit() or s[i] == '.'):
            raise ValueError
        start = i
        while i < len(s) and (s[i].isdigit() or s[i] == '.'):
            i += 1
        # must be followed by a unit letter
        if i >= len(s):
            raise ValueError
        unit = s[i]
        i += 1
        if unit not in units:
            raise ValueError
        unit_idx = units[unit]
        if unit_idx < last_unit_idx:
            raise ValueError
        last_unit_idx = unit_idx
        any_unit = True
        val = float(s[start:i-1])
        if unit == 'H':
            total += val * 3600
        elif unit == 'M':
            total += val * 60
        elif unit == 'S':
            total += val
    if not any_unit:
        raise ValueError
    return total

def main():
    # valid examples
    cases = [
        ("PT0S", 0),
        ("PT1H30M", 5400),
        ("P1DT2H", 93600),
        ("P1W", 604800),
        ("PT0.5S", 0.5),
        ("P2DT3H4M5.25S", 183845.25),
    ]
    for s, exp in cases:
        assert abs(iso_duration_seconds(s) - exp) < 1e-9
    # invalid inputs must raise ValueError
    invalid = ["", "P", "PT", "1H", "P1H", "P1DT"]
    for s in invalid:
        try:
            iso_duration_seconds(s)
            raise AssertionError(f"{s} should have raised")
        except ValueError:
            pass
    # extra valid case: P2W
    assert abs(iso_duration_seconds("P2W") - 2*604800) < 1e-9
    # extra valid case: P1DT1M (day + minute)
    assert abs(iso_duration_seconds("P1DT1M") - (86400 + 60)) < 1e-9
    print("ALL TESTS PASSED")

if __name__ == "__main__":
    main()

